"""Import the pinned, unmodified upstream source subset from an official tarball."""
import hashlib
import json
from pathlib import Path
import shutil
import sys
import tarfile
import tempfile
import xml.etree.ElementTree as ET

VERSION = '3.13.18'
SHA256 = 'abb0102e6d4ae027509bcb82327d9dd85515b44a3ba8ad538cfc5e9847029f68'
FROZEN = {
    '_frozen_importlib': 'Lib/importlib/_bootstrap.py',
    '_frozen_importlib_external': 'Lib/importlib/_bootstrap_external.py',
    'zipimport': 'Lib/zipimport.py',
    'abc': 'Lib/abc.py', 'codecs': 'Lib/codecs.py', 'io': 'Lib/io.py',
    '_collections_abc': 'Lib/_collections_abc.py',
    'encodings': 'Lib/encodings/__init__.py',
    **{f'encodings.{name}': f'Lib/encodings/{name}.py' for name in
       ('aliases', 'utf_8', 'ascii', 'latin_1', 'utf_8_sig', 'cp1252', 'mbcs')},
}


def main():
    archive = Path(sys.argv[1])
    if hashlib.sha256(archive.read_bytes()).hexdigest() != SHA256:
        raise SystemExit('CPython archive SHA-256 mismatch')
    destination = Path(__file__).resolve().parent
    if (destination / 'src').exists():
        raise SystemExit('src already exists; refuse to overwrite it')
    with tempfile.TemporaryDirectory(prefix='cpython-import-') as temporary:
        with tarfile.open(archive) as source:
            source.extractall(temporary, filter='data')
        root = Path(temporary) / f'Python-{VERSION}'
        project = ET.parse(root / 'PCbuild/_freeze_module.vcxproj')
        ns = {'m': 'http://schemas.microsoft.com/developer/msbuild/2003'}
        sources = [item.attrib['Include'].replace('..\\', '').replace('\\', '/')
                   for item in project.findall('.//m:ClCompile[@Include]', ns)]
        sources += ['Modules/_abc.c', 'Modules/_codecsmodule.c',
                    'Modules/_weakref.c', 'Modules/_threadmodule.c',
                    'Python/dynload_stub.c', 'Modules/mathmodule.c']
        files = set(sources) | set(FROZEN.values()) | {
            'LICENSE', 'Doc/license.rst', 'PC/pyconfig.h.in',
            'PCbuild/_freeze_module.vcxproj'}
        # obmalloc.c includes the bundled allocator as one translation unit.
        files.update(p.relative_to(root).as_posix()
                     for p in (root / 'Objects/mimalloc').rglob('*.c'))
        for folder in ('Include', 'Objects', 'Parser', 'Python', 'Modules', 'PC'):
            files.update(str(p.relative_to(root)).replace('\\', '/')
                         for p in (root / folder).rglob('*')
                         if p.is_file() and p.suffix in ('.h', '.inc'))
        manifest = {}
        for name in sorted(files):
            target = destination / 'src' / name
            target.parent.mkdir(parents=True, exist_ok=True)
            shutil.copyfile(root / name, target)
            manifest[name] = hashlib.sha256(target.read_bytes()).hexdigest()
        (destination / 'source_manifest.json').write_text(
            json.dumps(manifest, indent=2) + '\n', encoding='utf-8')
        (destination / 'frozen_modules.json').write_text(
            json.dumps(FROZEN, indent=2) + '\n', encoding='utf-8')
        core = sorted(set(sources) - {'Programs/_freeze_module.c',
            'PC/config_minimal.c', 'Modules/getpath_noop.c'})
        (destination / 'sources.gni').write_text(
            '# Generated by import_source.py from the pinned upstream project.\n'
            'cpython_core_sources = [\n' + ''.join(f'  "src/{p}",\n' for p in core)
            + ']\n', encoding='utf-8')
        print(f'Imported CPython {VERSION}: {len(files)} files, {len(core)} sources')


if __name__ == '__main__':
    main()
